import{_ as e,o as d,c as a,ag as i}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"EmakiItem","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/item/index.md","filePath":"en/modules/item/index.md","lastUpdated":null}'),o={name:"en/modules/item/index.md"};function r(n,t,s,l,c,m){return d(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="emakiitem" tabindex="-1">EmakiItem <a class="header-anchor" href="#emakiitem" aria-label="Permalink to &quot;EmakiItem&quot;">​</a></h1><p>EmakiItem provides lightweight custom items, stable item IDs, sets, trigger actions, auto update, and PlaceholderAPI support. It is often the starting point for equipment progression.</p><h2 id="module-facts" tabindex="-1">Module facts <a class="header-anchor" href="#module-facts" aria-label="Permalink to &quot;Module facts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>2.6.7</code></td></tr><tr><td>Main command</td><td><code>/emakiitem</code></td></tr><tr><td>Alias</td><td><code>/ei</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependencies</td><td>EmakiAttribute, EmakiSkills, PlaceholderAPI</td></tr><tr><td>Permissions</td><td><code>emakiitem.use</code>, <code>emakiitem.give</code>, <code>emakiitem.inspect</code>, <code>emakiitem.update</code>, <code>emakiitem.reload</code>, <code>emakiitem.debug</code>, <code>emakiitem.admin</code></td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Listing and giving items, inspecting the held item and its components, refreshing items and sets, reload and debug.</td></tr><tr><td><a href="./definitions.html">Definitions and Sets</a></td><td>The fields of <code>items/*.yml</code> and <code>sets/*.yml</code>, and how an item ID produces an ItemStack.</td></tr><tr><td><a href="./triggers.html">Triggers</a></td><td>Running actions on interact, attack, projectile, block, and drop events.</td></tr><tr><td><a href="./update.html">Update Strategy</a></td><td>Bringing items players already hold up to a changed definition.</td></tr><tr><td><a href="./repair.html">Repair System</a></td><td>The disabled state at zero durability and the material/currency repair flow.</td></tr><tr><td><a href="./integration.html">Cross-Module Integration</a></td><td>Item source syntax when Attribute, Forge, Strengthen, Gem, Skills, or Cooking reference an item.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Main-hand update, redraw, repair, durability, and vanilla data component actions.</td></tr><tr><td><a href="./api.html">API</a></td><td>Creating, identifying, and querying items through <code>EmakiItemApi</code>.</td></tr><tr><td><a href="./events.html">Event API</a></td><td>Bukkit events and interception points across the item flow.</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>Stable item ID</td><td>Uses config IDs instead of display names.</td></tr><tr><td>Item components</td><td>Configures material, name, lore, model, enchants, flags, durability, and more.</td></tr><tr><td>Attribute output</td><td>Can provide attribute payloads to Attribute.</td></tr><tr><td>Skill binding</td><td>Can expose skills or skill unlock data.</td></tr><tr><td>Set system</td><td>Grants attributes, skills, or lore based on equipped piece count.</td></tr><tr><td>Triggers</td><td>Runs actions on interaction, combat, projectile, block, drop, and other events.</td></tr><tr><td>Auto update</td><td>Refreshes item state on login, hand switch, inventory click, pickup, and similar cases.</td></tr><tr><td>Repair system</td><td>Items enter a disabled state at zero durability and can be repaired with materials or currency.</td></tr><tr><td>ID aliases and migration</td><td>Maps renamed item IDs and can migrate configs and player inventories in bulk.</td></tr></tbody></table><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to &quot;Default runtime folder&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiItem/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── id_aliases.yml</span></span>
<span class="line"><span>├── items/</span></span>
<span class="line"><span>├── sets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>items/</code> defines items, <code>sets/</code> defines item sets, <code>gui/</code> holds the repair interface template, and <code>id_aliases.yml</code> stores renamed item ID mappings.</p><h2 id="main-configuration" tabindex="-1">Main configuration <a class="header-anchor" href="#main-configuration" aria-label="Permalink to &quot;Main configuration&quot;">​</a></h2><p><code>config.yml</code> contains only global settings; item behavior lives in the individual definition files.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>Current module version</td><td>Marks the default config structure; manual edits are discouraged.</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>Language file ID, matching <code>lang/&lt;language&gt;.yml</code>.</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>Whether to release default sample data such as <code>items/</code> and <code>sets/</code>. This does not control <code>config.yml</code> or language files.</td></tr><tr><td><code>data_directories.max_depth</code></td><td>int</td><td><code>2</code></td><td>Maximum subdirectory scan depth for <code>items/</code> and <code>sets/</code>, counting the data directory itself. <code>1</code> reads only the root, <code>2</code> allows one level of subdirectories, <code>3</code> allows two. Directories beyond the limit are skipped with a console warning; the minimum value is <code>1</code>.</td></tr><tr><td><code>set_bonus.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Whether the set bonus system is enabled.</td></tr><tr><td><code>set_bonus.refresh_triggers.join</code></td><td>boolean</td><td><code>true</code></td><td>Refresh set state when a player joins.</td></tr><tr><td><code>set_bonus.refresh_triggers.held_change</code></td><td>boolean</td><td><code>true</code></td><td>Refresh when the held item changes.</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_click</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on inventory click.</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_drag</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on inventory drag.</td></tr><tr><td><code>set_bonus.refresh_triggers.pickup</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on item pickup.</td></tr><tr><td><code>set_bonus.refresh_triggers.interact</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on interaction.</td></tr><tr><td><code>set_bonus.refresh_triggers.command</code></td><td>boolean</td><td><code>true</code></td><td>Allow refresh when related commands run.</td></tr></tbody></table><p><code>set_bonus.refresh_triggers</code> controls set state refreshing, while item auto-update is controlled separately by <code>update.triggers</code> in an item definition; neither overrides the other.</p><h2 id="typical-item-lifecycle" tabindex="-1">Typical item lifecycle <a class="header-anchor" href="#typical-item-lifecycle" aria-label="Permalink to &quot;Typical item lifecycle&quot;">​</a></h2><ol><li>Define item IDs, material, name, lore, and components in <code>items/</code>.</li><li>Optionally add Attribute stats, Skills, or set info.</li><li>An administrator gives out the item.</li><li>A player uses the item.</li><li>Item automatically refreshes its state when triggered.</li><li>Forge / Strengthen / Gem can continue writing their own layers on top.</li><li>CoreLib rebuilds the final presentation.</li></ol><h2 id="relations-with-other-modules" tabindex="-1">Relations with other modules <a class="header-anchor" href="#relations-with-other-modules" aria-label="Permalink to &quot;Relations with other modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Integration</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>Item writes base or set attributes.</td></tr><tr><td>EmakiSkills</td><td>Item writes equipment skill IDs and forced equipment triggers. The PDC keys are owned by a standalone protocol module and do not depend on EmakiSkills being enabled.</td></tr><tr><td>EmakiForge</td><td>Forge can modify items created by EmakiItem.</td></tr><tr><td>EmakiStrengthen</td><td>Strengthen can strengthen EmakiItem equipment.</td></tr><tr><td>EmakiGem</td><td>Gem can add sockets and inlay gems onto EmakiItem equipment.</td></tr></tbody></table>`,19)])])}const p=e(o,[["render",r]]);export{u as __pageData,p as default};
